do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-020","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":987119002,"language":"nl"},"before":null,"after":{"work_id":987119002,"language":"nl","bound_author_id":987319002,"text":"Frans de Waal onderzoekt de plaats van empathie in het gedrag van mensen en andere dieren. Hij bespreekt onder meer zorg voor zieke soortgenoten, troost en het vormen van vertrouwensbanden. Die waarnemingen gebruikt hij om een mensbeeld ter discussie te stellen waarin alleen eigenbelang en concurrentie tellen. Het boek verbindt onderzoek naar sociaal gedrag met vragen over samenwerking in de samenleving. De Waal presenteert empathie daarbij als een vermogen met een evolutionaire achtergrond, waarvan mensen hun eigen handelen beter kunnen leren begrijpen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.atlascontact.nl/calendar/frans-de-waal-in-de-koninklijke-schouwburg-in-den-haag/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p401381463","http://data.bibliotheken.nl/id/nbt/p411240706","http://data.bibliotheken.nl/id/nbt/p396542727","http://data.bibliotheken.nl/id/nbt/p423479237","http://data.bibliotheken.nl/id/nbt/p412522322","http://data.bibliotheken.nl/id/nbt/p412975432"],"checked_at":"2026-11-02T21:47:08.214Z","reference":"work:5190","note":"Source person OL2628905A and exact-ISBN KB authority p068382618 share Q303350. Frans de Waal and Fransiscus Bernardus Maria de Waal are bound to the same author of The Age of Empathy; no same-name merge. Exact9789046705223 Olympus paperback.","canonical_name_resolution":"Same Wikidata person Q303350 in cached OL record and exact Dutch ISBN KB-linked person p068382618; also1948 birth."},{"type":"original_substantive_source_review","review":"content-review-029.json","sources":["https://www.atlascontact.n