it een gezamenlijk perspectief over ambities, liefde en de vraag wat van hun oorspronkelijke saamhorigheid overblijft wanneer een gedeelde onderneming eindigt.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.debezigebij.nl/boek/alle-tijd/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p42222829X"],"checked_at":"2026-11-02T21:47:08.214Z","reference":"work:1671","note":"Primary publisher credits Ronald Giphart for this same novel; KB exact2019ISBN9789403160405 binds Ronald Edgar Giphart. NS historical Treinlezer coupon independently binds the exact2019ISBN and publisher. The primary publisher current2023paperback ISBN9789403131467 is another printing, not substituted.","canonical_name_resolution":"Exact2019ISBN title statement and linked full-name author p092801668 bind Ronald Edgar; same public author credit on publisher page and NS original coupon. No author merge."},{"type":"original_substantive_source_review","review":"content-review-035.json","sources":["https://www.debezigebij.nl/boek/alle-tijd/","https://www.ns.nl/binaries/_ht_1598454936582/content/assets/ns-nl/treinlezer/coupon---alle-tijd-van-ronald-giphart.pdf","https://openlibrary.org/works/OL24409454W","https://data.bibliotheken.nl/id/nbt/p42222829X"]},{"type":"cover_front_review","cover_id":10952479,"sha256":"aadab6371bb12de31d9594db84132249858c61ae71420048dfebda8a938e894e","reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:47:08.214Z","review_batch":"nl-scale-20261102-020"}},{"ref":"m2","relation":"catalog_edition_metadata","key":{"edition_id":987219001},"before":null,"after":{"edition_id":987219001,"work_id":987119001,"bound_author_id":987319001,"bound_title":"Alle tijd","bound_language":